const IMG = {"gr": "data:image/jpeg;base64,", "slj": "data:image/jpeg;base64,", "sr": "data:image/jpeg;base64,", "dm": "data:image/jpeg;base64,", "dvf": "data:image/jpeg;base64,", "rh": "data:image/jpeg;base64,", "tk": "data:image/jpeg;base64,", "wh": "data:image/jpeg;base64,", "da": "data:image/jpeg;base64,", "dakr": "data:image/jpeg;base64,"};
// The 10 QR codes, in station order. The grid always uses this order, so everyone's grid has the same layout.
const STATIONS = [
  { k: "gr",   name: "Gordon Ramsay",          cls: "Teaches Cooking",                     stn: "The Kitchen",          pos: "90% 50%" },
  { k: "slj",  name: "Samuel L. Jackson",      cls: "Teaches Acting",                      stn: "The Stage",            pos: "50% 50%" },
  { k: "sr",   name: "Shonda Rhimes",          cls: "Teaches Writing for Television",      stn: "The Writers' Room",    pos: "50% 50%" },
  { k: "dm",   name: "deadmau5",               cls: "Teaches Electronic Music Production", stn: "The Booth",            pos: "50% 50%" },
  { k: "dvf",  name: "Diane von Furstenberg",  cls: "Teaches Building a Fashion Brand",    stn: "The Atelier",          pos: "50% 50%" },
  { k: "rh",   name: "Ron Howard",             cls: "Teaches Directing",                   stn: "The Director's Chair", pos: "30% 50%" },
  { k: "tk",   name: "Thomas Keller",          cls: "Teaches Cooking Techniques",          stn: "The Pass",             pos: "50% 50%" },
  { k: "wh",   name: "Werner Herzog",          cls: "Teaches Filmmaking",                  stn: "The Edit Bay",         pos: "70% 50%" },
  { k: "da",   name: "Dominique Ansel",        cls: "Teaches French Pastry Fundamentals",  stn: "The Pastry Bench",     pos: "50% 50%" },
  { k: "dakr", name: "David Axelrod & Karl Rove", cls: "Teach Campaign Strategy",          stn: "The War Room",         pos: "50% 50%" },
];
// Reward N goes to whoever makes their Nth unlock. Placeholders.
const REWARDS = [
  { t: "Welcome drink on us",          how: "Show this screen at the bar." },
  { t: "MasterClass sticker pack",     how: "Grab one at the welcome desk." },
  { t: "Skip the lunch line",          how: "Show this screen at lunch." },
  { t: "Offsite tote bag",             how: "Pick it up at the welcome desk." },
  { t: "Gift a year of MasterClass",   how: "A code lands in your inbox tonight." },
  { t: "Pick a song at dinner",        how: "Tell the DJ which instructor sent you." },
  { t: "Front-row keynote seat",       how: "Reserved under your name." },
  { t: "Limited-edition hoodie",       how: "Only 40 made. Collect at the desk." },
  { t: "Coffee with an exec",          how: "Pick who. We'll set it up." },
  { t: "Hunt Master",                  how: "All 10 found. You're in the grand prize draw." },
];
// Three people, three free-roam orders (station keys).
const PEOPLE = [
  { id: "A", label: "Person A", path: ["gr", "sr", "dm", "tk", "slj", "wh", "da", "rh", "dvf", "dakr"] },
  { id: "B", label: "Person B", path: ["dvf", "rh", "gr", "dakr", "wh", "slj", "sr", "tk", "dm", "da"] },
  { id: "C", label: "Person C", path: ["wh", "da", "slj", "sr", "dakr", "gr", "dvf", "dm", "rh", "tk"] },
];
const byKey = Object.fromEntries(STATIONS.map((s, i) => [s.k, { ...s, n: i + 1 }]));
const LOCK = '<svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" aria-hidden="true"><rect x="5" y="11" width="14" height="10" rx="2"/><path d="M8 11V8a4 4 0 0 1 8 0v3"/></svg>';
const esc = s => String(s).replace(/[&<>"]/g, c => ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;" }[c]));

// Scans so far = number of unique link pages this browser has visited (see cookies.js).
let step = Math.min(10, Math.max(1, window.HUNT.scanned.length));
let who = "A";

// A page can set window.HERO_VIDEO = "<YouTube id>" to autoplay that video in the first phone's big Unlocked tile.
// Browsers only allow autoplay when muted, so it starts muted; viewers can unmute from the player.
function heroVideo(s, p) {
  const id = window.HERO_VIDEO;
  if (!id || p !== PEOPLE[0]) return "";
  return `<iframe class="hero-video" src="https://www.youtube-nocookie.com/embed/${encodeURIComponent(id)}?autoplay=1&mute=1&playsinline=1&rel=0" title="${esc(s.name)} video" allow="accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture; web-share" referrerpolicy="strict-origin-when-cross-origin" allowfullscreen></iframe>`;
}

function phone(p) {
  const got = p.path.slice(0, step);
  const cur = byKey[got[got.length - 1]];
  const rw = REWARDS[step - 1];
  const nextRw = REWARDS[step];
  const tiles = STATIONS.map((s, i) => {
    const idx = got.indexOf(s.k);
    const open = idx >= 0;
    return `<div class="t ${open ? "" : "locked"} ${s.k === cur.k ? "current" : ""}">
      <div class="ph">
        <img src="${IMG[s.k]}" alt="${open ? esc(s.name) : ""}" style="object-position:${s.pos}">
        ${open ? `<span class="ord">${idx + 1}</span>` : `<span class="lock">${LOCK}</span>`}
      </div>
      <div class="lbl"><b>${open ? esc(s.name) : "Locked"}</b><span>${i + 1} · ${esc(s.stn)}</span></div>
    </div>`;
  }).join("");
  const pathTxt = got.map(k => byKey[k].stn.replace(/^The /, "")).join(" → ");
  return `
    <div class="person${p.id === who ? " active" : ""}">
      <p class="who"><b>${p.label}</b><span class="xs muted">just scanned ${esc(cur.stn)}</span></p>
      <div class="phone">
        <div class="topbar"><span class="wordmark">MASTERCLASS</span><span class="pill">${step} / 10</span></div>
        <div class="hero reveal">
          <div class="frame">
            ${heroVideo(cur, p) || `<img src="${IMG[cur.k]}" alt="${esc(cur.name)}">
            <div class="ov"></div>`}
            <span class="pill primary badge">Unlocked</span>
            <span class="pill stn">Station ${cur.n} · ${esc(cur.stn)}</span>
          </div>
          <div class="cap">
            <span class="count">Instructor ${step} of 10</span>
            <h3 class="name">${esc(cur.name)}</h3>
            <p class="cls">${esc(cur.cls)}</p>
          </div>
        </div>
        ${step === 10 ? `<div class="final"><div class="b1">All 10 found</div><p class="small" style="margin:6px 0 0">You're a Hunt Master.</p></div>` : ""}
        <div class="reward">
          <div class="head"><span class="pill gold">Reward ${step}</span><span class="xs muted">same for everyone at ${step}</span></div>
          <p class="title">${esc(rw.t)}</p>
          <p class="how">${esc(rw.how)}</p>
          <div class="bar"><i style="width:${step * 10}%"></i></div>
          ${nextRw ? `<div class="next">Next unlock: <b>${esc(nextRw.t)}</b></div>` : ""}
        </div>
        <div class="coll-h"><h3>Your instructors</h3><span class="xs muted">${10 - step} left to find</span></div>
        <div class="grid">${tiles}</div>
        <div class="path">Your path: <b>${esc(pathTxt)}</b></div>
      </div>
    </div>`;
}

function render() {
  document.getElementById("phones").innerHTML = PEOPLE.map(phone).join("");
  document.querySelectorAll("#steps button").forEach(b => b.setAttribute("aria-pressed", String(+b.dataset.n === step)));
  document.querySelectorAll("#tabs button").forEach(b => b.setAttribute("aria-selected", String(b.dataset.id === who)));
}

const stepsEl = document.getElementById("steps");
// Only steps you have reached can be selected; the rest unlock as you scan more links.
stepsEl.innerHTML = Array.from({ length: 10 }, (_, i) => `<button type="button" data-n="${i + 1}" aria-pressed="false"${i + 1 > window.HUNT.scanned.length ? " disabled" : ""}>${i + 1}</button>`).join("");
stepsEl.addEventListener("click", e => { const b = e.target.closest("button"); if (b && !b.disabled) { step = +b.dataset.n; render(); } });
document.getElementById("replay").addEventListener("click", render);
const tabsEl = document.getElementById("tabs");
tabsEl.innerHTML = PEOPLE.map(p => `<button type="button" role="tab" data-id="${p.id}">${p.label}</button>`).join("");
tabsEl.addEventListener("click", e => { const b = e.target.closest("button"); if (b) { who = b.dataset.id; render(); } });
render();
